form.script:
(function() {
    // Ensure this script runs after the DOM is fully loaded
    openerp.web.WebClient.include({
        start: function() {
            this._super.apply(this, arguments);
            var self = this;
            // Delay binding to ensure elements are in DOM, especially in complex views
            setTimeout(function() { self.bind_chat_events(); }, 500);
        },
        bind_chat_events: function() {
            var send_button = document.getElementById('send_query_button');
            var query_input = document.getElementById('chat_query_input');
            var history_display = document.getElementById('chat_history_display');

            if (send_button && query_input && history_display) {
                send_button.onclick = function() {
                    var query = query_input.value;
                    if (!query.trim()) return;

                    var user_msg_div = document.createElement('div');
                    user_msg_div.innerHTML = 'You: ' + query; // Consider escaping HTML in query
                    history_display.appendChild(user_msg_div);

                    openerp.session.rpc('/ollama_chatbot/chat', {query: query})
                        .then(function(result) {
                            var bot_response = (result && result.response) ? result.response : "No valid response from bot.";
                            var bot_msg_div = document.createElement('div');
                            bot_msg_div.innerHTML = 'Bot: ' + bot_response; // Consider escaping HTML in bot_response
                            history_display.appendChild(bot_msg_div);
                            history_display.scrollTop = history_display.scrollHeight;
                        })
                        .fail(function(error) {
                            var error_msg_div = document.createElement('div');
                            var error_message = "Could not reach bot.";
                            if (error && error.message && error.data && error.data.message){
                                error_message += " " + error.data.message;
                            } else if (error && error.message) {
                                error_message += " " + error.message;
                            }
                            error_msg_div.innerHTML = 'Error: ' + error_message;
                            history_display.appendChild(error_msg_div);
                            history_display.scrollTop = history_display.scrollHeight;
                            console.error("RPC Error:", error);
                        });
                    query_input.value = '';
                    query_input.focus();
                };

                query_input.onkeypress = function(e) {
                    if (e.key === 'Enter' || e.keyCode === 13) { // Check for Enter key
                        send_button.onclick(); // Trigger send button click
                    }
                };

            } else {
                console.warn("Chat UI elements not found. Retrying binding...");
                // Retry binding after a short delay if elements are not found
                // This can happen if the script executes before the elements are rendered
                var self_binder = this;
                setTimeout(function() { self_binder.bind_chat_events(); }, 1000);
            }
        }
    });
})();
